import customers from './customers.json' with {type:'json'};

const TOOLS = [
  {
    name: 'customer_lookup',
    description: 'Look up a customer by their customer id and return their details.',
    inputSchema: {
      type: 'object',
      properties: {
        customer_id: { type: 'string', description: 'The unique id of the customer to look up.' }
      },
      required: ['customer_id'],
      additionalProperties: false
    }
  }
];

export async function listTools() {
  return TOOLS;
}

function validateArgs(args) {
  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
    throw new Error('Invalid arguments: expected an object');
  }
  for (const key of Object.keys(args)) {
    if (key !== 'customer_id') {
      throw new Error(`Invalid argument: unexpected property '${key}'`);
    }
  }
  if (!('customer_id' in args)) {
    throw new Error("Invalid arguments: 'customer_id' is required");
  }
  if (typeof args.customer_id !== 'string') {
    throw new Error("Invalid arguments: 'customer_id' must be a string");
  }
  if (args.customer_id.length === 0) {
    throw new Error("Invalid arguments: 'customer_id' must not be empty");
  }
}

export async function callTool(name, args) {
  if (name !== 'customer_lookup') {
    throw new Error(`Unknown tool: ${name}`);
  }
  validateArgs(args ?? {});

  const id = args.customer_id;
  const customer = customers[id];
  if (!customer) {
    throw new Error(`Unknown customer: ${id}`);
  }

  const text = `${customer.name} (tier: ${customer.tier})`;
  return { content: [{ type: 'text', text }] };
}

